package org.mixxx;

import java.util.Set;

// Autonomously generated by an AI agent.
// Decides which flags the native layer receives when USB audio outputs change.
// Bit values match the constants in src/soundio/androidaudiofocus.cpp.
// End of comment autonomously generated by an AI agent.
final class HardwareChanges {
    static final int AUDIO = 1;
    static final int MIDI = 2;
    static final int ROUTE_LOST = 4;
    static final int OUTPUT_FAILED = 8;

    private HardwareChanges() { }

    static int audioOutputs(Set<Integer> previous, Set<Integer> current) {
        if (current.equals(previous)) {
            return 0;
        }
        boolean removed = !current.containsAll(previous);
        return AUDIO | (removed ? ROUTE_LOST : 0);
    }
}
